BIT_PRACTICE = [
    ("What is printed?\nprintf(\"%d\", 6 & 3);", ["2", "7", "5", "1"], 0, "110 & 011 = 010."),
    ("What is printed?\nprintf(\"%d\", 6 | 3);", ["7", "2", "5", "9"], 0, "110 | 011 = 111."),
    ("What is printed?\nprintf(\"%d\", 6 ^ 3);", ["5", "7", "2", "3"], 0, "110 ^ 011 = 101."),
    ("What is printed?\nprintf(\"%d\", ~6);", ["−7", "−6", "1", "9"], 0, "~x = −(x + 1)."),
    ("What is printed?\nprintf(\"%d\", 6 << 2);", ["24", "12", "8", "3"], 0, "6 × 4."),
    ("What is printed?\nprintf(\"%d\", 6 >> 1);", ["3", "12", "2", "1"], 0, "6 / 2."),
    ("What is printed?\nint x = 0xA5;\nprintf(\"%X\", x & 0x0F);", ["5", "A", "A5", "F"], 0, "The low nibble."),
    ("What is printed?\nprintf(\"%d\", 0xA5 >> 4);", ["10", "5", "165", "4"], 0, "The high nibble 0xA."),
    ("What is printed?\nprintf(\"%d\", (5 & 3) | (5 ^ 3));", ["7", "1", "6", "8"], 0, "1 | 6."),
    ("What is printed?\nprintf(\"%d\", ~(~5));", ["5", "−5", "−6", "4"], 0, "Complementing twice gives the original."),
    ("What is printed?\nprintf(\"%d %d\", !5, ~5);", ["0 −6", "0 −5", "−6 0", "1 −6"], 0, P + "! is logical NOT; ~ is bitwise NOT."),
    ("What is printed?\nunsigned char c = ~0;\nprintf(\"%d\", c);", ["255", "−1", "0", "65535"], 0, "All 8 bits set."),
    ("What is printed?\nint n = 255, c = 0;\nwhile (n) { c += n & 1; n >>= 1; }\nprintf(\"%d\", c);", ["8", "255", "7", "1"], 0, "255 = 11111111."),
    ("What is printed?\nprintf(\"%u\", 1u << 31);", ["2147483648", "−2147483648", "0", "31"], 0, "With unsigned, shifting into bit 31 is well defined."),
    ("What is printed?\nprintf(\"%d\", (13 >> 2) & 1);", ["1", "0", "3", "13"], 0, "13 = 1101; bit 2 is 1."),
    ("What is printed?\nprintf(\"%d\", 13 & ~4);", ["9", "13", "4", "8"], 0, "Clears bit 2: 1101 → 1001."),
    ("What is printed?\nprintf(\"%d\", 13 ^ 0xF);", ["2", "13", "15", "0"], 0, "1101 ^ 1111 = 0010."),
    ("What is printed?\nprintf(\"%d\", 12 & -12);", ["4", "12", "0", "8"], 0, P + "x & −x isolates the lowest set bit (12 = 1100)."),
    ("What is printed?\nif (8 & 4) printf(\"Y\"); else printf(\"N\");", ["N", "Y", "YN", "Nothing"], 0, "1000 & 0100 = 0."),
    ("What is printed?\nprintf(\"%d %d\", 8 & 4, 8 && 4);", ["0 1", "1 1", "0 0", "12 1"], 0, "Bitwise AND versus logical AND."),
    ("What is printed?\nprintf(\"%d\", 1 << 2 > 3);", ["1", "0", "4", "8"], 0, "<< before >: (1 << 2) > 3 → 4 > 3."),
    ("If x = 5, then after  x ^= 5;  x is", ["0", "10", "5", "1"], 0, "Any value XOR itself is 0."),
    ("With a = 3 and b = 5, the value of  a & b | a ^ b  is", ["7", "1", "6", "4"], 0, "& first (1), then ^ (6), then | → 7."),
    ("What is printed?\nint n = 7, p = 0;\nwhile (n) { p ^= n & 1; n >>= 1; }\nprintf(\"%d\", p);", ["1", "0", "3", "7"], 0, P + "Parity: 7 has three 1 bits (odd)."),
    ("(x << 4) − x equals", ["15x", "16x", "4x", "x⁴"], 0, "16x − x."),
    ("The condition  n & 1 == 0  is", ["Always 0 – == binds tighter than &, giving n & 0", "True for even n", "True for odd n", "A compile-time error"], 0,
     P + "Write (n & 1) == 0."),
    ("The value of  0xFF00 & 0x1234  is", ["0x1200", "0x0034", "0xFF34", "0x1234"], 0, "Only the high byte survives the mask."),
    ("The value of  (0x12 << 8) | 0x34  is", ["0x1234 (4660)", "0x3412", "0x46", "0x0034"], 0, "Combining two bytes into a 16-bit value."),
    ("The value of  10 & 9  is", ["8", "1", "11", "9"], 0, "1010 & 1001 = 1000 (n & (n − 1) clears the lowest set bit)."),
    ("The value of  0x3C ^ 0xFF  is", ["0xC3", "0x3C", "0xFF", "0x00"], 0, "XOR with all ones flips every bit of the byte."),
]

